import { useEffect, useMemo, useState, type FormEvent } from 'react';
import type { ActionDefinition, Actor, ChoiceRequest, Command, ContentEntry, ItemInstance, Position } from '../shared/model';
import { ABILITIES } from '../shared/model';
import { areaContains, resolveSpellArea } from '../shared/spell-geometry';
import { deriveActor } from '../engine/index';
import { api, type GameClient, useGame } from './transport';
import { ABILITY_LABELS, actorColor, actorInitial, CATEGORY_LABELS, CONDITIONS, DAMAGE_LABELS, downloadJson, isEditable, MAX_ARCHIVE_BYTES, parseLegacyFile, readLegacyStorage, resourceLabel, signed, SKILLS } from './client-utils';
import { AutomationBadge, categoryIs, contentById, Confirm, Empty, entryLabel, Field, Icon, Modal, ModalFeedbackContext } from './components';
import { CharacterEditor, LevelUpModal } from './CharacterEditor';
import { MapBoard } from './MapBoard';
import { SceneDialog } from './SceneDialog';
import { actionRangeLabel, availableActions } from './actions';
import { ActionOptions } from './ActionOptions';
import { HostStatusCard, useHostStatus } from './HostStatus';
import { GmWorldTools } from './GmWorldTools';
import { itemActionDefaults, itemSpellPreview } from './MagicItemOptions';
import { getItemAdapter } from '../content/item-adapters';
